class Persona:
    def __init__(self, nombre, tribu):
        self.nombre = nombre
        self.tribu = tribu

    def presentarse(self):
        return f"Soy {self.nombre}, de la tribu de {self.tribu}"

class Rey(Persona):
    def __init__(self, nombre, tribu, reino, anios):
        super().__init__(nombre, tribu)
        self.reino = reino
        self.anios = anios

    def reinar(self):
        return f"{self.nombre} reinó {self.anios} años sobre {self.reino}"

    def __str__(self):
        return f"Rey {self.nombre}"


david = Rey("David", "Judá", "Israel", 40)
print(david.presentarse())
print(david.reinar())
print(david)
print(isinstance(david, Persona))

